package net.cobbleservertools.roaming;
import java.io.*; import java.lang.reflect.*; import java.nio.file.*; import java.util.*; import java.util.concurrent.ConcurrentHashMap;
public final class RoamingPokemonManager {
 private static final int SPECIAL_ID=Integer.MIN_VALUE; private static final Map<UUID,Roamer> R=new ConcurrentHashMap<>(); private static Object serverRef; private static long ticks; private static boolean loaded;
 private RoamingPokemonManager(){}
 public static boolean tryHandleProfileUpdate(Object context,Object payload){try{int id=(Integer)payload.getClass().getMethod("entityId").invoke(payload);if(id!=SPECIAL_ID)return false;Runnable work=()->processProfileUpdate(context,payload);context.getClass().getMethod("enqueueWork",Runnable.class).invoke(context,work);return true;}catch(Throwable t){return false;}}
 private static void processProfileUpdate(Object context,Object payload){try{Object player=context.getClass().getMethod("player").invoke(context);Class<?> sp=Class.forName("net.minecraft.server.level.ServerPlayer");if(!sp.isInstance(player))return;Class<?> perm=Class.forName("net.cobbleservertools.util.NpcPermissions");if(!(Boolean)perm.getMethod("canModify",sp).invoke(null,player))return;Object tag=payload.getClass().getMethod("profile").invoke(payload);ensureLoaded(player.getClass().getMethod("getServer").invoke(player));Roamer r=Roamer.fromTag(tag);if(r.regions.isEmpty()){message(player,"Roaming Pokemon needs at least one roaming area.");return;}R.put(r.id,r);r.nextMigration=ticks+r.migrationSeconds*20L;save();announce("[Roaming Pokemon] A "+pretty(r.species)+" has begun roaming around "+r.regions.get(0).label()+"!");message(player,"Created roaming Pokemon: "+pretty(r.species)+" ("+r.id+")");}catch(Throwable ignored){}}
 public static void tickFromEvent(Object event){try{Object s=event.getClass().getMethod("getServer").invoke(event);tick(s);}catch(Throwable ignored){}}
 public static void tick(Object server){try{ensureLoaded(server);ticks++;if(ticks%20!=0)return;for(Roamer r:new ArrayList<>(R.values()))tickOne(server,r);}catch(Throwable ignored){}}
 private static void tickOne(Object server,Roamer r)throws Exception{if(r.caught)return;if(r.respawnAt>ticks)return;if(r.regions.isEmpty())return;if(r.nextMigration>0&&ticks>=r.nextMigration&&r.entityUuid==null){r.region=(r.region+1)%r.regions.size();r.nextMigration=ticks+r.migrationSeconds*20L;r.dwell.clear();announce("[Roaming Pokemon] "+pretty(r.species)+" migrated to "+r.regions.get(r.region).label()+".");save();}
  Object existing=r.entityUuid==null?null:findEntity(server,r.entityUuid); if(existing!=null){r.missingChecks=0;return;} if(r.entityUuid!=null){r.missingChecks++;if(r.missingChecks>=3){ if(isPokemonOwned(server,r.pokemonUuid)){r.caught=true;r.entityUuid=null;announce("[Roaming Pokemon] "+pretty(r.species)+" was caught! Its roaming journey has ended.");save();return;} r.entityUuid=null;r.pokemonUuid=null;r.pokemonRef=null;r.respawnAt=ticks+r.koRespawnSeconds*20L;r.dwell.clear();announce("[Roaming Pokemon] "+pretty(r.species)+" was defeated. It will return later.");save();}return;}
  Region a=r.regions.get(r.region); List<?> players=players(server); for(Object p:players){if(!a.contains(p))continue;UUID pu=(UUID)p.getClass().getMethod("getUUID").invoke(p);int d=r.dwell.merge(pu,20,Integer::sum);if(ticks-r.lastCry>=r.crySeconds*20L){playCry(p,r.species);r.lastCry=ticks;}if(d>=r.revealSeconds*20){Object ent=spawn(server,p,r);if(ent!=null){r.entityUuid=(UUID)ent.getClass().getMethod("getUUID").invoke(ent);Object pk=ent.getClass().getMethod("getPokemon").invoke(ent);r.pokemonUuid=(UUID)pk.getClass().getMethod("getUuid").invoke(pk);r.pokemonRef=pk;r.missingChecks=0;announce("[Roaming Pokemon] "+pretty(r.species)+" has appeared in "+a.label()+"!");save();return;}}}}
 private static Object spawn(Object server,Object player,Roamer r){try{String props=r.properties();Class<?> fac=Class.forName("net.cobbleservertools.battle.NpcPokemonFactory");Object pokemon=fac.getMethod("create",String.class,int.class,String.class,List.class).invoke(null,props,r.level,"",r.movesList());if(pokemon==null)return null;applyVariantAspects(pokemon,r.aspects);applyPokerus(pokemon,r.pokerus);Object level=player.getClass().getMethod("serverLevel").invoke(player);Class<?> pe=Class.forName("com.cobblemon.mod.common.entity.pokemon.PokemonEntity");Class<?> et=Class.forName("net.minecraft.world.entity.EntityType");Object type=Class.forName("com.cobblemon.mod.common.CobblemonEntities").getField("POKEMON").get(null);Constructor<?> ctor=null;for(Constructor<?> c:pe.getConstructors())if(c.getParameterCount()==3){ctor=c;break;}if(ctor==null)return null;Object ent=ctor.newInstance(level,pokemon,type);double x=((Number)player.getClass().getMethod("getX").invoke(player)).doubleValue()+4;double y=((Number)player.getClass().getMethod("getY").invoke(player)).doubleValue();double z=((Number)player.getClass().getMethod("getZ").invoke(player)).doubleValue()+4;ent.getClass().getMethod("setPos",double.class,double.class,double.class).invoke(ent,x,y,z);try{ent.getClass().getMethod("setPersistenceRequired").invoke(ent);}catch(Throwable ignored){}level.getClass().getMethod("addFreshEntity",Class.forName("net.minecraft.world.entity.Entity")).invoke(level,ent);return ent;}catch(Throwable t){return null;}}
 private static void applyVariantAspects(Object pokemon,String aspects){if(pokemon==null||aspects==null||aspects.isBlank())return;try{Set<String> set=new LinkedHashSet<>();try{Object cur=pokemon.getClass().getMethod("getForcedAspects").invoke(pokemon);if(cur instanceof Collection<?> c)for(Object x:c)if(x!=null)set.add(String.valueOf(x));}catch(Throwable ignored){}for(String a:aspects.split("[,;\\s]+"))if(!a.isBlank())set.add(a.trim().toLowerCase(Locale.ROOT));pokemon.getClass().getMethod("setForcedAspects",Set.class).invoke(pokemon,set);}catch(Throwable ignored){}}
 private static void applyPokerus(Object pokemon, boolean on) { PokerusCompat.apply(pokemon, on); }
 private static void playCry(Object player,String species){try{Object level=player.getClass().getMethod("serverLevel").invoke(player);double x=((Number)player.getClass().getMethod("getX").invoke(player)).doubleValue(),y=((Number)player.getClass().getMethod("getY").invoke(player)).doubleValue(),z=((Number)player.getClass().getMethod("getZ").invoke(player)).doubleValue();String sid=species.contains(":")?species.substring(species.indexOf(':')+1):species;Object rl=Class.forName("net.minecraft.resources.ResourceLocation").getMethod("fromNamespaceAndPath",String.class,String.class).invoke(null,"cobblemon","pokemon."+sid.replace("_","")+".ambient");Object reg=Class.forName("net.minecraft.core.registries.BuiltInRegistries").getField("SOUND_EVENT").get(null);Object sound=reg.getClass().getMethod("get",Class.forName("net.minecraft.resources.ResourceLocation")).invoke(reg,rl);Object source=Class.forName("net.minecraft.sounds.SoundSource").getField("NEUTRAL").get(null);for(Method m:level.getClass().getMethods())if(m.getName().equals("playSound")&&m.getParameterCount()>=7){Object[] a=new Object[m.getParameterCount()];a[0]=null;a[1]=x;a[2]=y;a[3]=z;a[4]=sound;a[5]=source;a[6]=1.0f;if(a.length>7)a[7]=1.0f;m.invoke(level,a);return;}}catch(Throwable ignored){}}
 private static boolean isPokemonOwned(Object server,UUID uuid){if(uuid==null)return false;try{Class<?> svc=Class.forName("net.cobbleservertools.battle.CobblemonPartyService"),sp=Class.forName("net.minecraft.server.level.ServerPlayer");Method party=svc.getMethod("party",sp);for(Object p:players(server)){for(Object mon:(List<?>)party.invoke(null,p)){if(mon!=null&&uuid.equals(mon.getClass().getMethod("getUuid").invoke(mon)))return true;}try{Object cob=Class.forName("com.cobblemon.mod.common.Cobblemon").getField("INSTANCE").get(null);Object storage=cob.getClass().getMethod("getStorage").invoke(cob);Object pc=null;for(Method m:storage.getClass().getMethods())if(m.getName().equals("getPC")&&m.getParameterCount()==1){pc=m.invoke(storage,p);break;}if(pc instanceof Iterable<?> it)for(Object mon:it)if(mon!=null&&uuid.equals(mon.getClass().getMethod("getUuid").invoke(mon)))return true;}catch(Throwable ignored){}}}catch(Throwable ignored){}return false;}
 private static Object findEntity(Object server,UUID id){try{for(Object level:(Iterable<?>)server.getClass().getMethod("getAllLevels").invoke(server)){Object e=level.getClass().getMethod("getEntity",UUID.class).invoke(level,id);if(e!=null)return e;}}catch(Throwable ignored){}return null;}
 private static List<?> players(Object server)throws Exception{Object pl=server.getClass().getMethod("getPlayerList").invoke(server);return (List<?>)pl.getClass().getMethod("getPlayers").invoke(pl);}
 private static void announce(String s){if(serverRef==null)return;try{for(Object p:players(serverRef))message(p,s);}catch(Throwable ignored){}}
 private static void message(Object p,String s){try{Object c=Class.forName("net.minecraft.network.chat.Component").getMethod("literal",String.class).invoke(null,s);p.getClass().getMethod("sendSystemMessage",Class.forName("net.minecraft.network.chat.Component")).invoke(p,c);}catch(Throwable ignored){}}
 private static void ensureLoaded(Object server){if(server==null)return;if(serverRef!=server){serverRef=server;loaded=false;R.clear();ticks=0;}if(!loaded){load();loaded=true;}}
 private static Path file(){try{Class<?> lr=Class.forName("net.minecraft.world.level.storage.LevelResource");Object root=lr.getField("ROOT").get(null);Path p=(Path)serverRef.getClass().getMethod("getWorldPath",lr).invoke(serverRef,root);return p.resolve("cobbleservertools").resolve("roaming_pokemon.properties");}catch(Throwable t){return Paths.get("cobbleservertools-roaming-pokemon.properties");}}
 private static void load(){Path f=file();if(!Files.isRegularFile(f))return;Properties p=new Properties();try(InputStream in=Files.newInputStream(f)){p.load(in);}catch(Exception e){return;}String ids=p.getProperty("ids","");for(String x:ids.split(","))if(!x.isBlank())try{UUID id=UUID.fromString(x);Roamer r=Roamer.fromProps(id,p);R.put(id,r);}catch(Exception ignored){}}
 private static void save(){try{Path f=file();Files.createDirectories(f.getParent());Properties p=new Properties();p.setProperty("ids",R.keySet().stream().map(UUID::toString).reduce((a,b)->a+","+b).orElse(""));for(Roamer r:R.values())r.toProps(p);try(OutputStream out=Files.newOutputStream(f)){p.store(out,"CobbleServerTools Roaming Pokemon NPCs");}}catch(Exception ignored){}}
 private static String str(Object tag,String k){try{return (String)tag.getClass().getMethod("getString",String.class).invoke(tag,k);}catch(Throwable t){return "";}}private static int num(Object tag,String k,int d){try{return (Integer)tag.getClass().getMethod("getInt",String.class).invoke(tag,k);}catch(Throwable t){return d;}}private static boolean bool(Object tag,String k){try{return (Boolean)tag.getClass().getMethod("getBoolean",String.class).invoke(tag,k);}catch(Throwable t){return false;}}private static float flt(Object tag,String k,float d){try{return (Float)tag.getClass().getMethod("getFloat",String.class).invoke(tag,k);}catch(Throwable t){return d;}}private static String pretty(String s){int i=s.indexOf(':');if(i>=0)s=s.substring(i+1);s=s.replace('_',' ');return s.isEmpty()?s:Character.toUpperCase(s.charAt(0))+s.substring(1);}
 private static final class Region{String dimension;double x,z,radius;static Region parse(String s){String[]a=s.split(",");if(a.length<4)return null;try{Region r=new Region();r.dimension=a[0];r.x=Double.parseDouble(a[1]);r.z=Double.parseDouble(a[2]);r.radius=Math.max(8,Double.parseDouble(a[3]));return r;}catch(Exception e){return null;}}String encode(){return dimension+","+x+","+z+","+radius;}String label(){return dimension+" near "+Math.round(x)+", "+Math.round(z)+" (r="+Math.round(radius)+")";}boolean contains(Object p){try{Object level=p.getClass().getMethod("serverLevel").invoke(p);Object key=level.getClass().getMethod("dimension").invoke(level);Object loc=key.getClass().getMethod("location").invoke(key);if(!dimension.equals(loc.toString()))return false;double px=((Number)p.getClass().getMethod("getX").invoke(p)).doubleValue(),pz=((Number)p.getClass().getMethod("getZ").invoke(p)).doubleValue();double dx=px-x,dz=pz-z;return dx*dx+dz*dz<=radius*radius;}catch(Throwable t){return false;}}}
 private static final class Roamer{UUID id=UUID.randomUUID(),entityUuid,pokemonUuid;transient Object pokemonRef;String species="suicune",nature="hardy",form="",aspects="",variantProperties="";int level=50;boolean shiny,pokerus,caught;float size=1;int[]iv={31,31,31,31,31,31},ev={0,0,0,0,0,0};String[]moves={"","","",""};List<Region>regions=new ArrayList<>();int region,koRespawnSeconds=1800,migrationSeconds=600,revealSeconds=20,crySeconds=12,missingChecks;long respawnAt,nextMigration,lastCry;Map<UUID,Integer>dwell=new HashMap<>();static Roamer fromTag(Object t){Roamer r=new Roamer();r.species=str(t,"RoamingSpecies");r.form=str(t,"RoamingForm");r.aspects=str(t,"RoamingAspects");r.variantProperties=str(t,"RoamingVariantProperties");r.level=num(t,"RoamingLevel",50);r.nature=str(t,"RoamingNature");r.shiny=bool(t,"RoamingShiny");r.pokerus=bool(t,"RoamingPokerus");r.size=flt(t,"RoamingSize",1);for(int i=0;i<6;i++){r.iv[i]=num(t,"RoamingIV"+i,31);r.ev[i]=num(t,"RoamingEV"+i,0);}for(int i=0;i<4;i++)r.moves[i]=str(t,"RoamingMove"+(i+1));for(String x:str(t,"RoamingRegions").split(";")){Region q=Region.parse(x);if(q!=null)r.regions.add(q);}r.koRespawnSeconds=num(t,"RoamingKoRespawnSeconds",1800);r.migrationSeconds=num(t,"RoamingMigrationSeconds",600);r.revealSeconds=num(t,"RoamingRevealSeconds",20);r.crySeconds=num(t,"RoamingCrySeconds",12);return r;}String properties(){String[]n={"hp","attack","defence","special_attack","special_defence","speed"};StringBuilder b=new StringBuilder(species).append(" level=").append(level).append(" shiny=").append(shiny);if(form!=null&&!form.isBlank())b.append(" form=").append(form);for(String vp:safeVariantProperties(variantProperties))b.append(' ').append(vp);if(nature!=null&&!nature.isBlank())b.append(" nature=").append(nature);for(int i=0;i<6;i++)b.append(' ').append(n[i]).append("_iv=").append(iv[i]).append(' ').append(n[i]).append("_ev=").append(ev[i]);List<String>m=movesList();if(!m.isEmpty())b.append(" moves=").append(String.join(",",m));if(SizeVariationCompat.isLoaded())b.append(" scale_modifier=").append(size);return b.toString();}List<String>movesList(){List<String>l=new ArrayList<>();for(String m:moves)if(m!=null&&!m.isBlank())l.add(m);return l;}void toProps(Properties p){String k=id+".";p.setProperty(k+"species",species);p.setProperty(k+"form",form==null?"":form);p.setProperty(k+"aspects",aspects==null?"":aspects);p.setProperty(k+"variantProperties",variantProperties==null?"":variantProperties);p.setProperty(k+"level",""+level);p.setProperty(k+"nature",nature);p.setProperty(k+"shiny",""+shiny);p.setProperty(k+"pokerus",""+pokerus);p.setProperty(k+"size",""+size);p.setProperty(k+"ivs",join(iv));p.setProperty(k+"evs",join(ev));p.setProperty(k+"moves",String.join(",",moves));p.setProperty(k+"regions",regions.stream().map(Region::encode).reduce((a,b)->a+";"+b).orElse(""));p.setProperty(k+"region",""+region);p.setProperty(k+"ko",""+koRespawnSeconds);p.setProperty(k+"mig",""+migrationSeconds);p.setProperty(k+"reveal",""+revealSeconds);p.setProperty(k+"cry",""+crySeconds);p.setProperty(k+"caught",""+caught);p.setProperty(k+"respawn",""+respawnAt);if(entityUuid!=null)p.setProperty(k+"entity",entityUuid.toString());if(pokemonUuid!=null)p.setProperty(k+"pokemon",pokemonUuid.toString());}static Roamer fromProps(UUID id,Properties p){Roamer r=new Roamer();r.id=id;String k=id+".";r.species=p.getProperty(k+"species","suicune");r.form=p.getProperty(k+"form","");r.aspects=p.getProperty(k+"aspects","");r.variantProperties=p.getProperty(k+"variantProperties","");r.level=Integer.parseInt(p.getProperty(k+"level","50"));r.nature=p.getProperty(k+"nature","hardy");r.shiny=Boolean.parseBoolean(p.getProperty(k+"shiny","false"));r.pokerus=Boolean.parseBoolean(p.getProperty(k+"pokerus","false"));r.size=Float.parseFloat(p.getProperty(k+"size","1"));r.iv=parseInts(p.getProperty(k+"ivs","31,31,31,31,31,31"),31);r.ev=parseInts(p.getProperty(k+"evs","0,0,0,0,0,0"),0);String[]m=p.getProperty(k+"moves",",,,").split(",",-1);for(int i=0;i<Math.min(4,m.length);i++)r.moves[i]=m[i];for(String x:p.getProperty(k+"regions","").split(";")){Region q=Region.parse(x);if(q!=null)r.regions.add(q);}r.region=Integer.parseInt(p.getProperty(k+"region","0"));r.koRespawnSeconds=Integer.parseInt(p.getProperty(k+"ko","1800"));r.migrationSeconds=Integer.parseInt(p.getProperty(k+"mig","600"));r.revealSeconds=Integer.parseInt(p.getProperty(k+"reveal","20"));r.crySeconds=Integer.parseInt(p.getProperty(k+"cry","12"));r.caught=Boolean.parseBoolean(p.getProperty(k+"caught","false"));r.respawnAt=Long.parseLong(p.getProperty(k+"respawn","0"));try{r.entityUuid=UUID.fromString(p.getProperty(k+"entity",""));}catch(Exception e){}try{r.pokemonUuid=UUID.fromString(p.getProperty(k+"pokemon",""));}catch(Exception e){}return r;}static List<String>safeVariantProperties(String s){List<String>o=new ArrayList<>();if(s==null||s.isBlank())return o;for(String raw:s.trim().split("\\s+")){int eq=raw.indexOf('=');if(eq<=0||eq>=raw.length()-1)continue;String k=raw.substring(0,eq).toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9_:\\-.]","");String v=raw.substring(eq+1).toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9_:\\-.]","");if(!k.isBlank()&&!v.isBlank())o.add(k+"="+v);}return o;}static String join(int[]a){StringBuilder b=new StringBuilder();for(int i=0;i<a.length;i++){if(i>0)b.append(',');b.append(a[i]);}return b.toString();}static int[]parseInts(String s,int d){int[]a=new int[6];Arrays.fill(a,d);String[]x=s.split(",");for(int i=0;i<Math.min(6,x.length);i++)try{a[i]=Integer.parseInt(x[i]);}catch(Exception ignored){}return a;}}
}
